public class Account {
    protected final String owner;
    protected double balance;

    public Account(String owner, double opening) {
        if (opening < 0) throw new IllegalArgumentException("opening can't be negative");
        this.owner = owner;
        this.balance = opening;
    }

    public void deposit(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        balance += amount;
    }

    public boolean withdraw(double amount) {
        if (amount <= 0) throw new IllegalArgumentException("amount must be positive");
        if (amount > balance) return false;
        balance -= amount;
        return true;
    }

    public double getBalance() { return balance; }
    public String summary() { return owner + ": " + balance; }
}

class GroupSavings extends Account {
    private final double rate;   // percent per month

    GroupSavings(String owner, double opening, double ratePercent) {
        super(owner, opening);
        this.rate = ratePercent;
    }

    @Override
    public boolean withdraw(double amount) {
        if (amount > balance / 2) return false;   // the group rule
        return super.withdraw(amount);           // the normal checks
    }

    public void monthEnd() {
        balance = Math.round(balance * (1 + rate / 100) * 100) / 100.0;
    }

    @Override
    public String summary() {
        return super.summary() + " (group, " + rate + "%)";
    }
}

