public abstract class Turret {
    private int ammo;

    protected Turret(int ammo) {
        if (ammo < 0) throw new IllegalArgumentException("ammo can't be negative");
        this.ammo = ammo;
    }

    public int getAmmo() { return ammo; }

    protected abstract int damage();
    protected abstract int ammoPerShot();

    // The steps are fixed here; children only fill in the numbers.
    public final int fire() {
        if (ammo < ammoPerShot()) return 0;
        ammo -= ammoPerShot();
        return damage();
    }

    public int fireAll() {
        int total = 0;
        int d;
        while ((d = fire()) > 0) total += d;
        return total;
    }
}

class Cannon extends Turret {
    Cannon(int ammo) { super(ammo); }
    @Override protected int damage() { return 40; }
    @Override protected int ammoPerShot() { return 2; }
}

class Laser extends Turret {
    Laser(int ammo) { super(ammo); }
    @Override protected int damage() { return 15; }
    @Override protected int ammoPerShot() { return 1; }
}
